cd /tmp/vally-eval-trial-VuCRI1 && cat > .copilot-tracking/skraft-plans/pricing/features/checkout-pricing-loyalty-discount.feature <<'EOF'
@loyalty-discount
Feature: Loyalty tier pricing at checkout
  As a returning customer
  I want my loyalty tier reflected in the checkout total
  So that the price I see rewards my history with the brand

  # SETTLED: Bronze, Silver and Gold (AC-1, AC-2, AC-3). Values copied verbatim from ac.md.
  # NOT SETTLED (no expected value exists, no test is authored):
  #   - Platinum tier: reduction not agreed by the business. Out of scope for M1.
  #   - AC-4 rounding: see the @needs-decision scenario below.

  @happy-path @smoke
  Scenario: Returning Bronze customer is charged 9500 cents for a 10000 cent basket
    Given a returning customer in the Bronze tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 9500 cents

  @happy-path
  Scenario: Returning Silver customer is charged 9000 cents for a 10000 cent basket
    Given a returning customer in the Silver tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 9000 cents

  @happy-path
  Scenario: Returning Gold customer is charged 8500 cents for a 10000 cent basket
    Given a returning customer in the Gold tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 8500 cents

  # NEEDS DECISION (escalated to DISCUSS): AC-4's title says the reduction lands on a whole
  # cent "in the customer's favour", but its example (Bronze, 7 cents -> charged 7 cents) means
  # a 0 cent reduction, the rounding LEAST favourable to the customer (5% of 7 = 0.35).
  # Title and example disagree. The example is recorded verbatim; no test is authored and no
  # rounding rule is implemented until the business confirms which is intended.
  @edge-case @needs-decision
  Scenario: Returning Bronze customer is charged 7 cents for a 7 cent basket
    Given a returning customer in the Bronze tier
    When a basket subtotal of 7 cents is priced
    Then the customer is charged 7 cents
EOF
cat > tests/CheckoutPricing.UnitTest/Features/LoyaltyDiscount/LoyaltyDiscountAcceptanceTests.cs <<'EOF'
using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.LoyaltyDiscount;

public class LoyaltyDiscountAcceptanceTests
{
    [Fact]
    public void Returning_Bronze_customer_is_charged_9500_cents_for_a_10000_cent_basket()
    {
        var pricing = new CalculateLoyaltyDiscount();

        var quote = pricing.Handle(new CalculateLoyaltyDiscountQuery(10000, LoyaltyTier.Bronze));

        Assert.Equal(9500, quote.TotalCents);
    }
}
EOF
echo done

